T = int(input())
for l in range(T):
	N = int(input())
	arr = input().split(' ')
	signs = []
	for p in range(N):
		signs.append(0)
		arr[p] = int(arr[p])
	count = 0
	if arr[0] < arr[1]:
		signs[0] = -1
		count += 1
	if arr[N - 1] < arr[N - 2]:
		signs[-1] = -1
		count += 1
	for k in range(1, N - 1):
		if arr[k] < arr[k + 1] and arr[k] < arr[k - 1]:
			signs[k] = -1
			count += 1

	def find(ptr):
		ptr += 1
		while ptr < N and signs[ptr] == 0:
			ptr += 1
		if ptr >= N:
			ptr = -1
		return ptr

	def sum(start, end):
		summer = start + 1
		sum = 0
		while summer != end:
			sum += arr[summer]
			summer += 1
		return sum
	if count >= 2:
		a = find(-1)
		b = find(a)
		c = find(b)
		while c != -1:
			if arr[a] + arr[b] >= sum(a, b):
				if arr[b] + arr[c] >= sum(b, c):
					ar = []
					ptr = a
					include_index = []
					while find(ptr) < N and find(ptr) != -1 and (arr[ptr] + arr[find(ptr)] >= sum(ptr, find(ptr))):
						ar.append(arr[ptr])
						include_index.append(ptr)
						ptr = find(ptr)
					ar.append(arr[ptr])
					include_index.append(ptr)
					max_include = []
					max_exclude = []
					for u in range(len(ar)):
						max_include.append(0)
						max_exclude.append(0)
					max_include[0] = ar[0]
					max_exclude[0] = 0
					Max = ar[0]
					for i in range(1, len(ar)):
						max_include[i] = max_exclude[i - 1] + ar[i]
						max_exclude[i] = max(max_include[i - 1], max_exclude[i - 1])
						Max = max(max_include[i], max_exclude[i])
					u = len(ar) - 1
					while u > 0:
						if max_include[u] <= max_exclude[u]:
							signs[include_index[u]] = 0
							u -= 1
						else:
							signs[include_index[u - 1]] = 0
							u -= 2
					a = ptr
					b = find(a)
					if b == -1:
						c = -1
					else:
						c = find(b)
					continue
				if arr[b] + arr[c] < sum(b, c):
					if arr[a] < arr[b]:
						signs[a] = 0
						a = b
					else:
						signs[b] = 0
					b = c
					c = find(c)
					continue
			if arr[a] + arr[b] < sum(a, b):
				a = b
				b = c
				c = find(c)
		if c == -1 and b != -1:
			if arr[a] + arr[b] >= sum(a, b):
				if arr[a] <= arr[b]:
					signs[a] = 0
				else:
					signs[b] = 0
	meaw = ''
	for p in range(N):
		if signs[p] == -1:
			meaw += str(-1 * arr[p]) + ' '
		else:
			meaw += str(arr[p]) + ' '
	print(meaw)
